'use strict';
const theoryState={tab:'guide',query:'',answers:{}};
const theoryTopics=[
 ['theme','Тақырып пен идея','Тақырып — шығармада суреттелген өмір құбылысы. Идея — автордың сол құбылыс туралы айтқысы келген ойы.','Тақырып: балалық шақтағы отбасылық тәрбие. Идеяны ашу үшін сол тәрбиенің бала дүниетанымына ықпалын дәлелде.','Үзінді не туралы? Автор осы мәселе жөнінде қандай ой ұсынады?','Кіріспе · А критерийі'],
 ['metaphor','Метафора','Бір нәрсені екіншісіне балау арқылы астарлы, бейнелі мағына беру. Тәсілді тыныс белгісінен ғана емес, мағынадан анықта.','«Желі — жібек» тіркесінде жел жібекке баланады.','Жібек бейнесінің қандай қасиеті желге ауыстырылған? Ол баланың қабылдауын қалай ашады?','Көркем тіл · А критерийі'],
 ['simile','Теңеу','Заттар мен құбылыстарды ұқсастығы арқылы салыстыру. -дай, -дей, -тай, -тей және «сияқты», «тәрізді», «секілді» сөздері жиі қолданылады.','«Жаңбыр жауса — жас баланың көз жасындай».','Не немен салыстырылған? Ұқсастық оқырманға қандай сезім тудырады?','Көркем тіл · А критерийі'],
 ['personification','Кейіптеу','Жансыз нәрсеге немесе табиғат құбылысына адамға тән әрекет пен сезім беру.','Табиғаттың «елжірей қарап», «аймалап әлдилеуі».','Табиғатқа қандай адамдық қасиет берілген? Бұл бала перспективасымен қалай байланысты?','Перспектива · А критерийі'],
 ['epithet','Эпитет','Заттың немесе құбылыстың ерекше сипатын бейнелі түрде айқындайтын сөз. Әрбір сын есім эпитет бола бермейді.','«Алыста қалған арайлы адал таңдарым менің».','«Арайлы», «адал» сөздері естеліктің қандай сипатын ашады? Баяндаушы көзқарасын қалай сездіреді?','Көзқарас · А критерийі'],
 ['repetition','Қайталау','Сөзді не тіркесті қайталап, ойға назар аударту және әсерді күшейту. Анафора — басында, эпифора — соңында қайталау.','«Содан қорқам» және кейінгі «... деп қорқамын» тіркестері.','Қандай алаңдаушылық күшейтіледі? Ол дәстүрдің ұрпаққа жалғасуына қалай қатысты?','Ұрпақ сабақтастығы · А критерийі'],
 ['contrast','Антитеза','Қарама-қарсы сипаттар мен ұғымдарды шендестіріп, олардың айырмасын айқындау.','Серкебайдың қызбалығы мен Қабылбектің сабырын қарама-қарсы қойып талдауға болады. Бұл — эпизодқа қатысты ықтимал түсіндіру.','Қай екі әрекет қарама-қарсы? Айырмашылық кейіпкерлердің мінезі мен көзқарасын қалай ашады?','Мінез · А критерийі'],
 ['composition','Композиция','Шығарма бөліктерінің өзара қисынды байланысы мен тұтастығы. Сюжетпен байланысты, бірақ оқиғаларды ретімен айтып берумен шектелмейді.','Кавказдағы түн көрінісінен балалық шақтағы түйелер арасындағы түнге ауысу.','Естелікке ауысудың қызметі қандай? Екі уақыт пен мекенді не байланыстырады?','Уақыт пен кеңістіктегі бағдар · А критерийі'],
 ['landscape','Пейзаж','Әдеби шығармадағы табиғаттың көркем бейнесі. Оны талдағанда көріністің шығармадағы қызметін түсіндір.','2-бөлімдегі тау, аспан, жел мен жаңбыр суреттері.','Табиғат жай көрініс болып тұр ма, әлде баланың сезімі мен дүниетанымын аша ма?','Перспектива · А критерийі'],
 ['citation','Дәйексөз және дәлел','Құжатта «дәйектеме (цитата)» — айтылған не жазылған ойдан сөзбе-сөз алынған үзінді. Дәйексөзді өз түсіндіруіңмен байланыстыр.','«Шырағы болсын, құлыным» (Б. Момышұлы, «Ұшқан ұя», 1-бөлім).','Осы сөз сенің тұжырымыңды қалай дәлелдейді? Терминді дәл қолданып, ойды анық жеткіздің бе?','А және Д · Академиялық адалдық']
];
const theoryQuestions=[
 ['«Автор қандай ой айтқысы келеді?» сұрағы нені анықтауға көмектеседі?',['Тақырыпты ғана','Идеяны','Өлең ұйқасын'],1,'Тақырып «не туралы?» дегенге, идея автордың сол мәселе туралы ойына жауап береді. Кіріспеде екеуін ажырат.'],
 ['«Желі — жібек» тіркесін метафора деп танудың негізгі себебі қандай?',['Сызықша тұрғандықтан ғана','Сөйлем қысқа болғандықтан','Жел жібекке бейнелі түрде баланғандықтан'],2,'Белгіге ғана сүйенбе. Жібектің жұмсақтық қасиеті желге ауыстырылған. Енді осы бейненің әсерін түсіндір.'],
 ['Қай қадам тәсілді атаудан талдауға көшіреді?',['Құралдың автор мақсаты мен оқырманға әсерін дәлелмен түсіндіру','Дәйексөзді ғана көшіру','Анықтаманы қайталау'],0,'Термин мен дәйексөз — бастама. Олардың мағынасы, мақсаты және әсері тұжырымыңды ашуы керек.']
];
function theoryPage(arg){if(arg&&theoryTopics.some(t=>t[0]===arg))theoryState.tab='guide';return head('ӘДЕБИ ТАЛДАУҒА ТІРЕК','Теория','Анықтаманы түсін. Мәтіннен дәлел тап. Автор таңдауының әсерін түсіндір.')+`<div class="tabs"><button data-theory-tab="guide" class="${theoryState.tab==='guide'?'selected':''}">Талдауға тірек</button><button data-theory-tab="source" class="${theoryState.tab==='source'?'selected':''}">Құжаттағы толық материал</button></div><p class="source-note">Қысқа анықтамалар мұғалім ұсынған «Теория.docx» негізінде бейімделді. «Ұшқан ұя» мысалдары мен бағыттаушы сұрақтар осы юнитке арналып қосылды. <a href="theory.docx" download>Word құжатын жүктеу</a></p>`+(theoryState.tab==='guide'?`<div class="callout"><b>Талдаудың бес қадамы</b><p>Тұжырым → дәйексөз → тәсіл мен мағына → автор мақсаты → оқырманға әсер.</p><p>Тәсіл атауын жатқа айту жеткіліксіз: оның дәл осы үзіндіде не үшін қолданылғанын түсіндір.</p></div><div class="tabs" aria-label="Теория тақырыптары">${theoryTopics.map(t=>`<a class="button secondary" href="#theory/${t[0]}">${t[1]}</a>`).join('')}</div>${theoryTopics.map(t=>`<article class="card theory-topic" id="theory-${t[0]}" style="margin:20px 0;scroll-margin-top:24px"><small>${t[5]}</small><h2>${t[1]}</h2><p>${t[2]}</p><p><b>Мәтінмен байланыс:</b> ${t[3]}</p><div class="callout"><b>Өзіңе сұрақ қой</b><p>${t[4]}</p></div><a class="text-link" href="#workshop">Шеберханада қолданып көр →</a></article>`).join('')}<section class="card"><h2>Түсінгеніңді тексер</h2>${theoryQuestions.map((q,i)=>`<section style="margin:24px 0"><h3>${i+1}. ${q[0]}</h3>${q[1].map((a,j)=>`<button class="choice ${theoryState.answers[i]===j?'chosen':''}" data-theory-question="${i}" data-theory-answer="${j}">${a}</button>`).join('')}<div id="theory-feedback-${i}" class="feedback" role="status">${theoryState.answers[i]!==undefined?theoryFeedback(i):''}</div></section>`).join('')}</section><div class="actions"><a class="button" href="#workshop">Үзінді талдауға өту →</a><a class="button secondary" href="#criteria">А және Д критерийлері</a></div>`:`<label for="theory-search">Материалдан сөз іздеу</label><input type="text" id="theory-search" value="${esc(theoryState.query)}" placeholder="Мысалы: метафора" style="width:100%"><p class="hint">Іздеу сөз кездесетін әліпбилік бөлімді мысалдарымен бірге көрсетеді.</p><div id="theory-source-results">${theorySourceResults()}</div><p class="source-note">Түпнұсқа анықтамалар мен мысалдар сақталған; бос жолдар мен жеке тұрған бет нөмірлері веб-нұсқада түсірілді. Құжаттағы өлеңтану ұғымдарын прозалық үзіндіге орынсыз қолданба: қажет терминді талдау мақсатына сай таңда.</p>`);}
function theoryFeedback(i){const q=theoryQuestions[i];return `<b>${theoryState.answers[i]===q[2]?'Дұрыс.':'Қайта ойлан.'}</b><p>${q[3]}</p>`;}
function theorySourceResults(){const q=theoryState.query.trim().toLocaleLowerCase('kk'),groups=THEORY_SOURCE.filter(g=>!q||g.letter.toLocaleLowerCase('kk').includes(q)||g.paragraphs.some(p=>p.toLocaleLowerCase('kk').includes(q)));return `<p class="hint" role="status">${groups.length} бөлім көрсетілді.</p>`+groups.map(g=>`<details ${q?'open':''}><summary>${esc(g.letter)} · ${g.paragraphs.length} мәтін бөлігі</summary><div class="reading">${g.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div></details>`).join('')+(!groups.length?'<p class="empty">Сөз табылмады. Қысқа түбірімен немесе басқа терминмен іздеп көр.</p>':'');}
function theoryEnhance(view,arg){
 if(view==='theory'&&arg&&theoryTopics.some(t=>t[0]===arg))requestAnimationFrame(()=>document.getElementById('theory-'+arg)?.scrollIntoView());
 if(view==='lessons'&&arg!==undefined){const keys=['theme','citation','contrast','metaphor','repetition','composition'],t=theoryTopics.find(t=>t[0]===keys[Number(arg)]);if(t)document.querySelector('#view .callout')?.insertAdjacentHTML('afterend',`<p class="callout"><b>Теориялық тірек:</b> <a href="#theory/${t[0]}">${t[1]} →</a> Анықтаманы оқып, төмендегі тапсырмада қолдан.</p>`);}
 if(view==='workshop')document.querySelector('#view .unit-idea')?.insertAdjacentHTML('afterend','<p class="callout"><b>Теория:</b> <a href="#theory/theme">Тақырып пен идея</a> · <a href="#theory/metaphor">Метафора</a> · <a href="#theory/simile">Теңеу</a> · <a href="#theory/personification">Кейіптеу</a> · <a href="#theory/composition">Композиция</a></p>');
 if(view==='final')document.querySelector('#view .hint')?.insertAdjacentHTML('afterend','<p class="hint">Қажет ұғымды <a href="#theory">Теория</a> бөлімінен қарап, өз талдауыңа дәл қолдан.</p>');
}
document.addEventListener('click',event=>{const tab=event.target.closest('[data-theory-tab]');if(tab){theoryState.tab=tab.dataset.theoryTab;history.replaceState(null,'','#theory');render();return;}const button=event.target.closest('[data-theory-question]');if(button){const i=Number(button.dataset.theoryQuestion),a=Number(button.dataset.theoryAnswer);theoryState.answers[i]=a;document.querySelectorAll(`[data-theory-question="${i}"]`).forEach(b=>b.classList.toggle('chosen',Number(b.dataset.theoryAnswer)===a));document.getElementById('theory-feedback-'+i).innerHTML=theoryFeedback(i);}});
document.addEventListener('input',event=>{if(event.target.id==='theory-search'){theoryState.query=event.target.value;document.getElementById('theory-source-results').innerHTML=theorySourceResults();}});
